import { cliFetch, httpError, isAbortError, networkError, unreadableBodyError } from "./api.js";
import { NeonApiError, createNeonClient } from "@neon/sdk";
// src/neon_client.ts
/**
* The `@neon/sdk` ergonomic client, for commands that run one of its multi-step workflows,
* with the timeout, debug logging, user agent, and 423 retries of `getApiClient`. Throws;
* pass failures through {@link fromSdkError}.
*/
const getNeonClient = ({ apiKey, apiHost, requestTimeoutMs }) => createNeonClient({
	apiKey,
	baseUrl: apiHost ?? "https://console.neon.tech/api/v2",
	fetch: cliFetch(requestTimeoutMs),
	retries: 5,
	throwOnError: true
});
/**
* Map an error from {@link getNeonClient} for the top-level handler. A management API
* response becomes the CLI's `NeonApiError`, so 401 and SSO recovery apply, and a request
* timeout becomes the same `ECONNABORTED` error the raw client throws. Anything else
* keeps the SDK's message and drops its `cause`, so a socket code deep in the chain cannot
* turn a "role was created, but…" message into the generic connectivity hint.
*/
function fromSdkError(error, apiHost) {
	const base = apiHost ?? "https://console.neon.tech/api/v2";
	if (error instanceof NeonApiError && error.response?.url.startsWith(base)) return error.response.ok ? unreadableBodyError(error.response, error.body) : httpError(error.response, error.body);
	if (isAbortError(error)) return networkError(error);
	return new Error(error instanceof Error ? error.message : String(error));
}
export { fromSdkError, getNeonClient };
